float random(vec2 uv, float time)
{
    return fract((sin(uv.x * time)) * 123.456 * (cos(uv.y * time) * 456.789));
}

float random(vec2 uv)
{
    return fract((sin(uv.x)) * 123.456 * (cos(uv.y) * 456.789));
}

vec2 RandomDir(vec2 uv, float t) {
    return sign(vec2(
        random(uv, t-fract(t)),
        random(uv * 10., t-fract(t))
    ) - 0.5);
}

float circle(vec2 p, float r) {
    return length(p) - r;
}

float InOutExpo(float x) {
    return x == 0.
    ? 0.
    : x == 1.
    ? 1.
    : x < 0.5 ? pow(2.0, 20. * x - 10.) * 0.5
    : (2. - pow(2.0, -20. * x + 10.)) * 0.5;
}

float OutInExpo(float x) {
    return x == 0.
    ? 0.
    : x == 1.
    ? 1.
    : x < 0.5 ? sin(x*3.14)*0.5
    : (1.0-sin(x*3.14)*0.5);
} 

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord / iResolution.y;
    vec2 o = vec2(0.5);
    float t = iTime * 0.8;

    float grid = 25.0;
    vec2 _uv = fract(uv * grid);
    vec2 tilePos = floor(uv * grid);
    float tileId = tilePos.x + tilePos.y * grid; 

    float animDir = random(tilePos);
    float u = OutInExpo(fract(t));


    float circleRadius = 0.25 + 0.25 * (1.0 * sin(fract(t)*3.14));
    float circleThickness = 0.18;
    vec2 circlePos0 = _uv - o + RandomDir(tilePos, t) * (u);
    vec2 circlePos1 = _uv - o + RandomDir(tilePos, t) * (u-1.0);
    vec2 circlePos2 = _uv - o + RandomDir(tilePos, t) * (u+1.0);

    float distToCircleEdge0 = circle(circlePos0, circleRadius);
    float distToCircleEdge1 = circle(circlePos1, circleRadius);
    float distToCircleEdge2 = circle(circlePos2, circleRadius);

    float circle = smoothstep(0.01, 0.002, abs(distToCircleEdge0)*circleThickness);  
    circle = max(circle, smoothstep(0.01, 0.002, abs(distToCircleEdge1)*circleThickness));  
    circle = max(circle, smoothstep(0.01, 0.002, abs(distToCircleEdge2)*circleThickness));  


    vec4 col = vec4(1.0);
    col.rgb = vec3(circle);
    fragColor = col; 
}
